111	namespace sg { namespace fused { namespace sm90 {
112	
113	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor
114	// slice at `off` within the flat [m|v|extra] layout. Per-TENSOR fields (the
115	// NeuralGrok psi MLP weights) and all scalars pass through unchanged.
116	template <OptId Opt>
117	__device__ __forceinline__ FusedOptState
118	rebase_state(const FusedOptState& s, int64_t off) {
119	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
120	    if (t.exp_avg)    t.exp_avg    += off;
121	    if (t.exp_avg_sq) t.exp_avg_sq += off;
122	    if (t.ema)        t.ema        += off;
123	    if (t.sam_dir)    t.sam_dir    += off;
124	    if (t.s_track)    t.s_track    += off;
125	    if (t.mu)         t.mu         += off;
126	    if (t.orth)       t.orth       += off;
127	    if (t.smart_grad) t.smart_grad += off;
128	    if (t.param_init) t.param_init += off;   // Prodigy trajectory anchor p0
129	    if (t.sharpness)  t.sharpness  += off;   // SuperGrok11/15 (g_sam−g)² (per element)
130	    // SuperGrok11/15 phi weights (sg_phi_W1/b1/W2) are a per-TENSOR weight SET (same
131	    // for every element), NOT a per-element slice — so they are NOT rebased (the same
132	    // pointer is staged to SMEM once per block, exactly like NeuralGrok's psi pointers).
133	    return t;
134	}
135	
136	// The L3-REAL decoder megakernel needs the token path + a grad-partial workspace
137	// in addition to the FuseTier::{L1,L3} ABI. We keep it a SEPARATE kernel +
138	// launcher (not folded into fused_megakernel) so the surrogate path is untouched.
139	//
140	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
141	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
142	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
143	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
144	// total == kDecTotalElems == 422755.
145	
146	struct DecoderTokenCtx {
147	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
148	    const int* targets;  // [B]       int32 target ids
149	    int        B;        // batch size (full-batch in the race ≈ 4191)
150	    float*     workspace; // grad partials + loss partials + reduced loss
151	    float*     loss_out;  // device float the kernel writes the mean loss into
152	};
153	
154	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
155	//    threads/CTA. The smem holds ONE DecSampleSmem (≈42 KB, < 48 KB static cap —
156	//    no dynamic-smem opt-in, so the occupancy≥1 guard with dynamicSMemBytes=0 in
157	//    the launcher is unchanged). ────────────────────────────────────────────────
158	// sizes/offsets are NOT host-passed: the per-tensor numel/offset live in the
159	// generated __constant__ tables kDecSizes/kDecOffsets (decoder_layout.cuh), so
160	// the reduce + optimizer phases read them directly. This also lets the host side
161	// (dispatch.cpp) avoid building any layout tensors.
162	template <OptId Opt>
163	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
164	fused_decoder_megakernel(PersistentContext ctx,
165	                         float* __restrict__ params,
166	                         DecoderTokenCtx tok,
167	                         float* __restrict__ grad,        // reduced grad [total]
168	                         float lr, int step, FusedOptState st) {
169	    __shared__ DecSampleSmem sm;
170	    GridBarrier bar = ctx.barrier();
171	    const int cta = blockIdx.x;
172	    const int nCTA = (int)ctx.n_ctas;
173	    const int64_t total = kDecTotalElems;
174	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
175	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
176	
177	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
178	    const int wg = threadIdx.x / 128;
179	    // warp-specialize prims live in sg::sm90::wgs (this file is sg::fused::sm90)
180	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
181	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
182	
183	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
184	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
185	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
186	    bar.sync();   // B0
187	
188	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
189	    DecWeights w = dec_bind(params);
190	    DecGrad g = dec_bind_grad(my_partial);
191	    // Even split with remainder to the low CTAs (contiguous, deterministic).
192	    const int B = tok.B;
193	    const int base = B / nCTA, rem = B % nCTA;
194	    const int b0 = cta * base + (cta < rem ? cta : rem);
195	    const int cnt = base + (cta < rem ? 1 : 0);
196	    const int b1 = b0 + cnt;
197	    __shared__ int tok_s[dec::kSeq];   // this sample's token ids (broadcast)
198	    __shared__ int tgt_s;
199	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
200	    for (int b = b0; b < b1; ++b) {
201	        if (threadIdx.x < dec::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * dec::kSeq + threadIdx.x];
202	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
203	        __syncthreads();
204	        float nll = dec_forward_sample(w, tok_s, tgt_s, &sm);
205	        dec_backward_sample(w, g, tok_s, tgt_s, B, &sm);
206	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
207	        __syncthreads();   // sample boundary: all grad writes done before reuse
208	    }
209	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
210	    bar.sync();   // B1: all CTA partials + loss slots complete
211	
212	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
213	    //    (one task = one parameter tensor; sum its elements across CTAs in
214	    //    ascending CTA index). The summation ORDER (ascending cta) is fixed, so
215	    //    the result is deterministic regardless of which CTA grabs the task. ────
216	    {
217	        __shared__ int task_slot;
218	        TaskQueue q = ctx.queue();
219	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
220	             t = q.next_block(&task_slot)) {
221	            const int n = kDecSizes[t];
222	            const int64_t off = (int64_t)kDecOffsets[t];
223	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
224	                float acc = 0.0f;
225	                // ascending CTA index → fixed fp32 summation order (deterministic).
226	                for (int c = 0; c < nCTA; ++c)
227	                    acc += tok.workspace[(int64_t)c * total + off + i];
228	                grad[off + i] = acc;
229	            }
230	        }
231	    }
232	    // Loss reduction (fp64 ordered) by CTA 0 only — the 1e-5 loss rel-tol is the
233	    // tightest gate; fp32 atomic-summing ~4191 terms can miss it.
234	    if (cta == 0 && threadIdx.x == 0) {
235	        double s = 0.0;
236	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
237	        float mean = (float)(s / (double)B);
238	        *tok.loss_out = mean;
239	    }
240	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
241	
242	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
243	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
244	    st.lr = lr;
245	    {
246	        __shared__ int task_slot;
247	        TaskQueue q = ctx.queue();
248	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
249	             t = q.next_block(&task_slot)) {
250	            const int n = kDecSizes[t];
251	            const int64_t off = (int64_t)kDecOffsets[t];
252	            const FusedOptState ts = rebase_state<Opt>(st, off);
253	            float* __restrict__ p = params + off;
254	            const float* __restrict__ gg = grad + off;
255	            for (int i = threadIdx.x; i < n; i += blockDim.x)
256	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
257	        }
258	    }
259	}
260	
261	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
262	//    Mirrors launch_fused_megakernel's hang-freedom contract: occupancy≥1 or
263	//    refuse (the GridBarrier rendezvous of n_ctas CTAs can never complete if a
264	//    CTA can't be placed). Zeroes the barrier+task counters per launch. ─────────
265	template <OptId Opt>
266	cudaError_t launch_fused_decoder_megakernel(
267	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
268	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
269	    int dev = 0;
270	    cudaError_t err = cudaGetDevice(&dev);
271	    if (err != cudaSuccess) return err;
272	    int n_sms = 0;
273	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
274	    if (err != cudaSuccess) return err;
275	
276	    int occ = 0;
277	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
278	        &occ, (const void*)&fused_decoder_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
279	        /*dynamicSMemBytes=*/0);
280	    if (err != cudaSuccess) return err;
281	    // Hang-freedom: at least one CTA per SM must be resident or the grid barrier
282	    // can never be satisfied. The L3-REAL kernel uses ≈42 KB static smem + a high
283	    // register count; if it cannot place one block/SM, REFUSE rather than hang.
284	    assert(occ >= 1 &&
285	           "fused_decoder_megakernel: 0 blocks/SM — GridBarrier would hang. The "
286	           "decoder smem (~42KB) + regs exceed one-block-per-SM occupancy; "
287	           "reduce footprint or fall back to the L1 per-op path.");
288	    if (occ < 1) return cudaErrorLaunchOutOfResources;
289	
290	    const unsigned launch_ctas = (unsigned)n_sms;
291	    ctx.n_ctas = launch_ctas;
292	
293	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
294	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
295	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
296	
297	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
298	    fused_decoder_megakernel<Opt><<<grid, block, 0, stream>>>(
299	        ctx, params, tok, grad, lr, step, st);
300	    return cudaGetLastError();
301	}
302	
303	// ════════════════════════════════════════════════════════════════════════════
304	//  WGMMA CELL DRIVER (DESIGN-TC-PIPELINE.md Fork B, R2.3). Compiled only under
305	//  the wgmma token; the scalar path above is untouched.
306	// ════════════════════════════════════════════════════════════════════════════
307	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
308	
309	// TC megakernel threads: 256 (the engine's producer+consumer warpgroup layout;
310	// wgmma is warpgroup-scoped on threads 0..127). We do NOT apply the scalar
311	// path's asymmetric setmaxnreg (dealloc<32> on WG0) — that would STARVE the MMA
312	// warpgroup (WG0 issues the wgmma; a 128-wide accumulator needs 64 fp32 regs/
313	// thread). The validated selftest ran no split; we match it.
314	#define SG_TC_MEGA_BLOCK 256
315	
316	// ── smem arena for the unpipelined engine: one A(64×16) + one B(N×16) bf16 tile
317	//    + the 256-float reduction slot. 16B-aligned. N = SG_TUNED_TILE_N. The 9 dW
318	//    specs live here too (identical for all threads → shared, not per-thread
319	//    stack: keeps the launch's local-memory reservation small so the persistent
320	//    kernel places on a memory-tight GPU). ──
321	struct DecTcSmem {
322	    // kDecTcStages A(64×16) + kDecTcStages B(N×16) bf16 tiles — the GEMM K-loop
323	    // double-buffer ring (slot s at sA + s*64*16 / sB + s*N*16). At S=2 + N=128
324	    // the ring is 2·(2KB+4KB)=12KB; DecTcSmem total ~13.5KB ≪ the 48KB static cap.
325	    __nv_bfloat16 sA[dectc::kDecTcStages * 64 * 16];
326	    __nv_bfloat16 sB[dectc::kDecTcStages * SG_TUNED_TILE_N * 16];
327	    float red[256];
328	    dectc::DecDwSpec spec[9];
329	};
330	
331	// ── TC workspace layout (carved from tok.workspace; the host sizes it for the
332	//    TC path — see dec_tc_workspace_floats). Regions (float units):
333	//      [0 .. acts_f)                      : DecActs bf16 region (reinterpreted)
334	//      [acts_f .. acts_f + nCTA*scratch)  : per-CTA tile scratch (f32)
335	//      [.. + nCTA*kLnVecElems)            : per-CTA LN-vec partials (f32)
336	//      [.. + nCTA)                        : per-CTA loss slots (f32)
337	//      [.. + 1)                           : reduced scalar loss (host reads it)
338	//    acts_f = ceil(acts_bf16 / 2). ──
339	__host__ __device__ __forceinline__ int64_t dec_tc_acts_floats(int T, int B) {
340	    // mirror dectc::dec_acts_bind's running offset (bf16 elems) → floats.
341	    const int64_t d = dec::kD, dff = dec::kDff, V = dec::kVocab, L = dec::kLayers;
342	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
343	    int64_t bf = 0;
344	    for (int li = 0; li < L; ++li) bf += Td + Td + Td + Tff + T3d + Td + Tff + Td;
345	    bf += (int64_t)B * d + (int64_t)B * V + Td;     // X_hn + dY_logits + dh0
346	    return (bf + 1) / 2;
347	}
348	// dW split-K partial floats (0 when G==1 → no extra scratch, single-CTA path).
349	__host__ __device__ __forceinline__ int64_t dec_tc_dw_part_floats() {
350	    return (dectc::kDecDwSplitK > 1) ? dectc::dec_dw_part_floats(dectc::kDecDwSplitK) : 0;
351	}
352	// STAGED-optimizer cross-CTA reduction scratch (Prodigy d-estimate). The Prodigy
353	// stage publishes per-CTA (r,s) slots (2*nCTA) + a reduced-d slot (1) — an owner-
354	// computes tree (opt_stages_precompute.cuh), NO float atomic. Sized for the
355	// LARGEST nCTA (one CTA/SM = #SMs); tiny (≤ 2*132+1 ≈ 1 KB) and carved
356	// UNCONDITIONALLY so the opt-agnostic host launcher (dec_tc_launcher_scratch)
357	// allocates one workspace that fits every OptId. Unused by AdamW/Lion/… (their
358	// P3 never touches this region), so adding it leaves those cells byte-identical.
359	__host__ __device__ __forceinline__ int64_t dec_tc_opt_reduce_floats(int nCTA) {
360	    return (int64_t)2 * nCTA + 1;            // [r slots | s slots | reduced d]
361	}
362	// ── Muon (STAGED grid-cooperative Newton-Schulz) per-matrix scratch. IDENTICAL in
363	//    shape to the vit twin (vit_tc_muon_floats): the NS chain runs ONE 2D weight at
364	//    a time over all CTAs; the scratch holds X/A/AX/AAX/orth for the LARGEST 2D weight
365	//    + the per-CTA Frobenius-norm partials + inv_norm. The momentum buffer (muon_buf)
366	//    is NOT here — it PERSISTS across steps as optimizer state, bound to the m slice
367	//    (st.exp_avg). Largest decoder 2D weight: ff.0/ff.2 = 512×128 = 65536 numel; largest
368	//    rows = 512 ⇒ A = 512×512 (dectc::kDecMuonMaxNumel/kDecMuonMaxRows). Carved
369	//    UNCONDITIONALLY (≈ 4·65536 + 512² + nCTA + 1 floats ≈ 2 MB) so the opt-agnostic
370	//    launcher (dec_tc_launcher_scratch) fits every OptId; unused by every non-Muon cell
371	//    (its P2.7/P3-2D branches are if-constexpr'd out → byte-identical). ──
372	__host__ __device__ __forceinline__ int64_t dec_tc_muon_floats(int nCTA) {
373	    // X + AX + AAX + orth (each maxNumel) + A (maxRows²) + nrm_partials(nCTA) + inv_norm(1)
374	    return (int64_t)4 * dectc::kDecMuonMaxNumel
375	         + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows
376	         + nCTA + 1;
377	}
378	// ── LookSAM (STAGED in-kernel SAM 2nd backward) transient scratch. The SAM step
379	//    perturbs p in place, runs a SECOND fwd+bwd at p', and needs (a) a param BACKUP
380	//    for the exact restore (eager clones p before perturbing) + (b) a SEPARATE g_sam
381	//    grad buffer so the 2nd backward does NOT clobber the first grad `grad` (sam_dir
382	//    = g_sam − grad reads both). Both are total-sized + transient (NOT persistent
383	//    state — sam_dir itself persists in the `extra` state slice, bound by the cell).
384	//    Carved UNCONDITIONALLY (≈ 2·422755 ≈ 3.4 MB) so the opt-agnostic launcher fits
385	//    every OptId; unused by every non-LookSAM cell (its phase is if-constexpr'd out
386	//    → byte-identical). nrm_partials(nCTA)+inv_norm(1) for the ‖g‖ reduction reuse
387	//    the loss workspace (sq_part/coef_bc, as GrokAdamW's P2.5 does), so no extra here. ──
388	__host__ __device__ __forceinline__ int64_t dec_tc_looksam_floats() {
389	    return (int64_t)2 * kDecTotalElems;       // [sam_backup | sam_grad]
390	}
391	__host__ __device__ __forceinline__ int64_t dec_tc_workspace_floats(int T, int B, int nCTA) {
392	    return dec_tc_acts_floats(T, B)
393	         + (int64_t)nCTA * dectc::dec_tile_scratch_total_f32()
394	         + (int64_t)nCTA * dectc::kLnVecElems
395	         + nCTA + 1
396	         + dec_tc_dw_part_floats()            // split-K dW partials (G>1)
397	         + dec_tc_opt_reduce_floats(nCTA)     // STAGED-opt (Prodigy) reduce slots
398	         + dec_tc_muon_floats(nCTA)           // STAGED-opt (Muon) NS per-matrix scratch
399	         + dec_tc_looksam_floats();           // STAGED-opt (LookSAM) SAM 2nd-bwd scratch
400	}
401	
402	template <OptId Opt>
403	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
404	fused_decoder_megakernel_tc(PersistentContext ctx,
405	                            float* __restrict__ params,
406	                            DecoderTokenCtx tok,
407	                            float* __restrict__ grad,
408	                            float lr, int step, FusedOptState st) {
409	    __shared__ DecTcSmem sm;
410	    GridBarrier bar = ctx.barrier();
411	    const int cta = blockIdx.x;
412	    const int nCTA = (int)ctx.n_ctas;
413	    const int B = tok.B;
414	    const int T = B * dec::kSeq;
415	
416	    // Workspace partition.
417	    float* ws = tok.workspace;
418	    const int64_t acts_f = dec_tc_acts_floats(T, B);
419	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
420	    float* scratch_base = ws + acts_f;
421	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
422	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
423	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
424	    float* loss_out   = loss_part + nCTA;
425	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
426	    // loss slot (matches dec_tc_workspace_floats's term order). G==1 → dw_part unused.
427	    float* dw_part    = loss_out + 1;
428	    const int kDwG    = dectc::kDecDwSplitK;
429	    // STAGED-opt cross-CTA reduce slots (Prodigy d), carved AFTER the dW partials
430	    // (matches dec_tc_workspace_floats's term order). Unused unless Opt==Prodigy.
431	    float* opt_reduce = dw_part + dec_tc_dw_part_floats();
432	    // Muon NS per-matrix scratch, carved AFTER the Prodigy reduce slots (matches
433	    // dec_tc_workspace_floats's term order — carving it LAST keeps every prior
434	    // region's offset unchanged, so the 5 already-green cells are byte-identical).
435	    // Unused unless Opt==Muon. Layout (mirrors the vit twin):
436	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kDecMuonMaxNumel)
437	    //   [muon_A (kDecMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
438	    float* muon_base = opt_reduce + dec_tc_opt_reduce_floats(nCTA);
439	    // LookSAM SAM 2nd-backward scratch, carved AFTER the Muon scratch (term order
440	    // matches dec_tc_workspace_floats — carving it LAST keeps every prior region's
441	    // offset unchanged, so the already-green cells are byte-identical). Layout:
442	    //   [sam_backup (total)] [sam_grad (total)]. Unused unless Opt==LookSAM.
443	    float* sam_backup = muon_base + dec_tc_muon_floats(nCTA);
444	    float* sam_grad   = sam_backup + kDecTotalElems;
445	
446	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
447	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
448	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
449	
450	    DecWeights w = dec_bind(params);
451	
452	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
453	    //    written-once → no pre-zero). ──
454	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
455	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
456	    bar.sync();   // B0
457	
458	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
459	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
460	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
461	    const int nrows_tile = dectc::kTileM;
462	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
463	    float nll_acc = 0.0f;
464	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
465	        const int g0 = ti * nrows_tile;
466	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
467	        float nll = dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
468	                                              sm.sA, sm.sB, sm.red);
469	        dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
470	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
471	        if (threadIdx.x == 0) nll_acc += nll;
472	        __syncthreads();
473	    }
474	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
475	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
476	
477	    // ── P2: assemble all 30 grads into `grad`. dW output-stationary (gt %
478	    //    nCTA), biases, embedding owner-scan, LN-vec reduce. No partials. The 9
479	    //    dW specs are built into SHARED smem (thread 0; identical for all) so the
480	    //    9-spec array is NOT on every thread's stack (shrinks the launch's local
481	    //    reservation — the persistent kernel must place on a memory-tight GPU). ──
482	    if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
483	    __syncthreads();
484	    dectc::DecDwSpec* spec = sm.spec;
485	    const int n_dw = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
486	    if (kDwG > 1) {
487	        // SPLIT-K (multi-CTA tiling): fan (n_dw·G) (tile,chunk) partials over the
488	        // grid so the ~62% idle SMs do work; deterministic ascending-chunk reduce.
489	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {
490	            const int gt = item / kDwG, kc = item % kDwG;
491	            dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
492	        }
493	        bar.sync();   // all (gt,kc) partials complete before the reduce reads them
494	        dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec, n_dw, kDwG, dw_part, grad, cta, nCTA);
495	    } else {
496	        for (int gt = cta; gt < n_dw; gt += nCTA)
497	            dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
498	    }
499	    dectc::dectc_dw_biases(spec, grad);
500	    dectc::dectc_embed_owner_scan(acts, tok.tokens, T, grad, cta, nCTA);
501	    dectc::dectc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
502	    // Loss reduce (fp64) by CTA 0.
503	    if (cta == 0 && threadIdx.x == 0) {
504	        double s = 0.0;
505	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
506	        *tok.loss_out = (float)(s / (double)B);
507	    }
508	    (void)loss_out;
509	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
510	
511	    // ── P2.4 (LookSAM ONLY, SAM steps): the MODEL-COUPLED SAM 2nd backward that
512	    //    produces st.sam_dir = g_sam − g (INTEGRATION-OPTSTAGES §6). Eager LookSAM,
513	    //    every k steps (looksam.py sam_step + looksam.h:27-59):
514	    //      ‖g‖     = GLOBAL L2 norm over ALL reduced grads (compute_sam_grad_norm_
515	    //                device_side); rho_over_norm = rho/‖g‖
516	    //      p'      = p + rho_over_norm·g          (perturb in the grad direction;
517	    //                backup = p.clone() for the exact restore — fp32 add is not
518	    //                bit-reversible, so we MUST save, not subtract back)
519	    //      g_sam   = ∇L(p')                       (a FULL SECOND in-kernel fwd+bwd
520	    //                + deterministic grad assembly at the perturbed weights, written
521	    //                to the SEPARATE `sam_grad` buffer so `grad` (the first grad the
522	    //                apply tail blends from) is untouched)
523	    //      sam_dir = g_sam − g                    (cached in the PERSISTENT `extra`
524	    //                state slice == st.sam_dir; reused verbatim on the k−1 intervening
525	    //                steps where looksam_sam==0, so NO 2nd pass runs then)
526	    //      restore p = backup
527	    //    The apply tail (P3, apply_optimizer<LookSAM>) then blends g_adj=(1−α)g+α·
528	    //    sam_dir and runs AdamW — UNCHANGED. DETERMINISM: the ‖g‖ reduction is the
529	    //    IDENTICAL deterministic ascending-CTA shape as GrokAdamW's P2.5 (fixed
530	    //    contiguous per-CTA range → per-CTA partial → CTA0 ascending sum), and the
531	    //    2nd fwd+bwd+assembly reuses the SAME A/A/A-clean machinery as the first pass
532	    //    (fixed tile ownership, ascending-k reductions), so the whole phase is
533	    //    deterministic BY CONSTRUCTION. Guarded so every other opt's path is
534	    //    byte-identical (no extra barrier / work). On a NON-SAM step (looksam_sam==0)
535	    //    this whole block is skipped — st.sam_dir already holds the cached direction.
536	    //
537	    //    SuperGrok11/15 SHARE this exact SAM 2nd-backward machinery (INTEGRATION-
538	    //    OPTSTAGES §4/§5): the perturb→2nd in-kernel fwd+bwd→restore pipeline is
539	    //    IDENTICAL; only the elementwise WRITE in step (d) differs — LookSAM writes
540	    //    st.sam_dir[i] = g_sam − g, SG11/15 write st.sharpness[i] = (g_sam − g)²
541	    //    (supergrok11_sm90.cuh:246 / supergrok15_sm90.cuh:315). sharpness is then the
542	    //    2nd MLP input the P2.45 meta-net mu precompute reads. The SAM-step gate is the
543	    //    SAME st.looksam_sam host scalar (the SG sam_step cadence); on a non-SAM step
544	    //    the cached sharpness is reused verbatim. SG reuses st.rho as the perturbation
545	    //    radius (its own sam_rho), identical reduction/perturb math.
546	    if constexpr (Opt == OptId::LookSAM || Opt == OptId::SuperGrok11 ||
547	                  Opt == OptId::SuperGrok15) {
548	        if (st.looksam_sam != 0.0f) {
549	            // (a) GLOBAL ‖g‖ over the reduced grad, deterministic (reuse the loss
550	            //     workspace as P2.5 does: loss_part[nCTA] = per-CTA Σg², loss_out[1]
551	            //     broadcasts rho_over_norm). The reduced loss is already in
552	            //     *tok.loss_out (host state), so this is free scratch.
553	            float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
554	            float* ron_bc  = loss_out;           // [1] broadcast rho_over_norm
555	            const int64_t total = kDecTotalElems;
556	            {
557	                const int64_t base = total / nCTA, rem = total % nCTA;
558	                const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
559	                const int64_t ecnt = base + (cta < rem ? 1 : 0);
560	                float tsum = 0.0f;
561	                for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
562	                    const float gv = grad[e0 + i];
563	                    tsum += gv * gv;
564	                }
565	                float* red = sm.red;
566	                red[threadIdx.x] = tsum;
567	                __syncthreads();
568	                for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
569	                    if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
570	                    __syncthreads();
571	                }
572	                if (threadIdx.x == 0) sq_part[cta] = red[0];
573	                bar.sync();   // B2.4a: all per-CTA Σg² partials complete
574	                if (cta == 0 && threadIdx.x == 0) {
575	                    double ss = 0.0;
576	                    for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
577	                    const float gnorm = sqrtf((float)ss);
578	                    // rho / ‖g‖ (matches bindings.cpp looksam_perturb_all). gnorm>0 in
579	                    // any real training step; guard div-by-0 → 0 (no perturb) to be safe.
580	                    *ron_bc = (gnorm > 0.0f) ? (st.rho / gnorm) : 0.0f;
581	                }
582	                bar.sync();   // B2.4b: rho_over_norm broadcast ready
583	            }
584	            const float rho_over_norm = *ron_bc;
585	            // (b) Backup + perturb p in place: p' = p + rho_over_norm·g. Grid-strided
586	            //     over the flat param vector (each element owned once → no race).
587	            {
588	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
589	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
590	                     i < total; i += gstride) {
591	                    sam_backup[i] = params[i];
592	                    params[i] = params[i] + rho_over_norm * grad[i];
593	                }
594	            }
595	            bar.sync();   // B2.4c: all params perturbed before the 2nd forward reads them
596	            // (c) SECOND fwd+bwd at the perturbed weights → g_sam in `sam_grad`. Mirror
597	            //     P1 + P2 EXACTLY, but: re-zero the lnvec partials (they accumulate),
598	            //     do NOT write the loss (keep the first-pass loss), and assemble into
599	            //     `sam_grad` (NOT `grad`). `w` wraps `params` (now perturbed) so the
600	            //     tile fns read the perturbed weights with no re-bind needed.
601	            for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
602	            bar.sync();   // B2.4d: lnvec partials cleared before the 2nd backward accumulates
603	            for (int ti = cta; ti < n_tiles; ti += nCTA) {
604	                const int g0 = ti * nrows_tile;
605	                const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
606	                dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
607	                                          sm.sA, sm.sB, sm.red);
608	                dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
609	                                           my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
610	                __syncthreads();
611	            }
612	            bar.sync();   // B2.4e: all 2nd-pass acts (X + dY) + LN-vec partials complete
613	            // Re-build the dW specs from the 2nd-pass acts (dY adjoints changed).
614	            if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
615	            __syncthreads();
616	            dectc::DecDwSpec* spec2 = sm.spec;
617	            const int n_dw2 = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec2);
618	            if (kDwG > 1) {
619	                for (int item = cta; item < n_dw2 * kDwG; item += nCTA) {
620	                    const int gt = item / kDwG, kc = item % kDwG;
621	                    dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec2, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
622	                }
623	                bar.sync();
624	                dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec2, n_dw2, kDwG, dw_part, sam_grad, cta, nCTA);
625	            } else {
626	                for (int gt = cta; gt < n_dw2; gt += nCTA)
627	                    dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec2, gt, sam_grad, sm.sA, sm.sB);
628	            }
629	            dectc::dectc_dw_biases(spec2, sam_grad);
630	            dectc::dectc_embed_owner_scan(acts, tok.tokens, T, sam_grad, cta, nCTA);
631	            dectc::dectc_lnvec_reduce(lnvec_base, sam_grad, nCTA, cta);
632	            bar.sync();   // B2.4f: g_sam fully assembled in sam_grad
633	            // (d) WRITE the SAM side-channel (into the persistent state slice) + restore p.
634	            //     LookSAM → sam_dir = g_sam − g; SuperGrok11/15 → sharpness = (g_sam − g)².
635	            {
636	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
637	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
638	                     i < total; i += gstride) {
639	                    const float diff = sam_grad[i] - grad[i];
640	                    if constexpr (Opt == OptId::LookSAM) {
641	                        // st.sam_dir is the extra-slice base (host-bound). g_sam − g.
642	                        const_cast<float*>(st.sam_dir)[i] = diff;
643	                    } else {
644	                        // SuperGrok11/15: sharpness = (g_sam − g)² (persisted state slice).
645	                        const_cast<float*>(st.sharpness)[i] = diff * diff;
646	                    }
647	                    params[i] = sam_backup[i];   // restore the ORIGINAL weights
648	                }
649	            }
650	            bar.sync_reset(ctx.g_next_task);   // B2.4g: params restored + side-channel ready; reset queue for P3
651	        }
652	    }
653	
654	    // ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. Eager
655	    //    grokadamw clips the WHOLE grad set to grad_clip via a GLOBAL L2 norm
656	    //    (clip_grad_norms_device_side → total_norm = sqrt(Σ_i ‖g_i‖²),
657	    //    clip_coef = grad_clip/(total_norm+1e-6) when total_norm>grad_clip,
658	    //    else 1) BEFORE the apply. We replicate it on the REDUCED grad with a
659	    //    deterministic ascending reduction (no float atomics): each CTA sums a
660	    //    contiguous element-range into a per-CTA partial slot, CTA0 sums the
661	    //    partials in ascending CTA order → total_norm → clip_coef, broadcast via
662	    //    a workspace slot. The grad buffer is NOT mutated (the return_grad oracle
663	    //    + the eager-side clip must both see the unclipped reduced grad); the
664	    //    coefficient is applied per-element inside apply_optimizer<GrokAdamW>.
665	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
666	    if constexpr (Opt == OptId::GrokAdamW) {
667	        // Reuse the (now-consumed) loss workspace: loss_part[nCTA] holds per-CTA
668	        // partial sum-of-squares; loss_out (1 float) broadcasts clip_coef. The
669	        // reduced loss is already in *tok.loss_out (state), so this is free scratch.
670	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
671	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
672	        // Per-CTA contiguous element range over `grad` (the reduced grad, [total]).
673	        const int64_t total = kDecTotalElems;
674	        const int64_t base = total / nCTA, rem = total % nCTA;
675	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
676	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
677	        // Thread-local partial → block reduce (fixed tree) → thread0 writes the slot.
678	        float tsum = 0.0f;
679	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
680	            const float gv = grad[e0 + i];
681	            tsum += gv * gv;
682	        }
683	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
684	        float* red = sm.red;
685	        red[threadIdx.x] = tsum;
686	        __syncthreads();
687	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
688	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
689	            __syncthreads();
690	        }
691	        if (threadIdx.x == 0) sq_part[cta] = red[0];
692	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
693	        // CTA0 ascending-order reduce → total_norm → clip_coef (deterministic).
694	        if (cta == 0 && threadIdx.x == 0) {
695	            double ss = 0.0;
696	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
697	            const float total_norm = sqrtf((float)ss);
698	            float coef = 1.0f;
699	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
700	                coef = st.grad_clip / (total_norm + 1e-6f);
701	            *coef_bc = coef;
702	        }
703	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
704	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
705	    }
706	
707	    // ── P2.6 (PRODIGY ONLY): STAGED cross-ALL-tensors d-estimate. The apply tail
708	    //    (apply_optimizer<Prodigy>) reads st.d_factor (the effective LR scale d),
709	    //    a GLOBAL reduction over EVERY element of EVERY tensor. We compute it here,
710	    //    BYTE-FAITHFUL to the live eager multi-tensor path (prodigy_sm90.cuh:465-
711	    //    544, the order prodigy.py → _ops.prodigy_fused_step actually executes):
712	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state
713	    //                slot would give d_prev=0 ⇒ d=0 ⇒ frozen params; eager inits
714	    //                _d_lr=d0=1e-6, so seed it here, the grokfast-style step-1 fix)
715	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
716	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
717	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
718	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
719	    //
720	    //    DETERMINISM — FIXED-PARTITION reduction (mirrors the A/A/A-CLEAN GrokAdamW
721	    //    P2.5 grad-norm reduce above), NOT the work-steal task-queue drain. WHY THIS
722	    //    SHAPE: the previous form drained the global TaskQueue (q.next_block →
723	    //    atomicAdd(g_next_task)) inside phaseA and reset that SAME counter in a
724	    //    sync_RESET barrier (B2.6a). The work-steal claim order is timing-dependent,
725	    //    so each CTA's (r,s) slot holds a potentially DIFFERENT tensor subset run-to-
726	    //    run; because fp32 add is non-associative, the per-CTA partials then regroup
727	    //    the same values differently and the owner's d can differ at ULP level from
728	    //    step>=2 (a COMPONENT_CONTRACT deterministic-reduction violation — even where
729	    //    it happens to be empirically bit-exact on a given GPU/workload, it is not
730	    //    deterministic BY CONSTRUCTION). GrokAdamW's P2.5 reduces a FIXED contiguous
731	    //    element range per CTA with a plain sync() and is A/A/A-CLEAN; prodigy now
732	    //    uses the IDENTICAL shape — deterministic by construction, independent of CTA
733	    //    timing. Each CTA owns [e0,e0+ecnt) of the FLAT [0,total) arrays —
734	    //    params/param_init/grad are parallel flat blobs, so a contiguous flat range
735	    //    sum == the cross-all-TENSORS sum (tensor boundaries are irrelevant to a
736	    //    global Σ). The per-element contribution still CALLS the canonical
737	    //    prodigy_partials_step (prodigy.h:28-53, single-source). NO float atomic;
738	    //    per-CTA (r,s) slot publish → ONE plain grid barrier → CTA0 owner-sums
739	    //    ascending → EMA-decay/update_d → broadcast → ONE plain grid barrier.
740	    //    g_next_task is UNTOUCHED here (B2 already reset it to 0), so P3's queue
741	    //    drain runs unchanged — no sync_reset needed in P2.6.
742	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
743	    if constexpr (Opt == OptId::Prodigy) {
744	        // Per-CTA (r,s) slots in opt_reduce ([r slots | s slots]) + the reduced-d
745	        // broadcast slot. d_prev: persisted d_lr (slot 2), or d0 cold-start at step 1.
746	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
747	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
748	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
749	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
750	        // FIXED contiguous element range over the flat [0,total_p) arrays (same split
751	        // as GrokAdamW P2.5: even base + remainder to the low CTAs → deterministic).
752	        const int64_t total_p = kDecTotalElems;
753	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
754	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
755	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
756	        float r_acc = 0.0f, s_acc = 0.0f;
757	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
758	            // Canonical per-element partials (prodigy.h:28-53): r carries d²·<g,p0−p>,
759	            // s carries d²·|g| (the L1-norm denominator). params/param_init/grad are
760	            // flat blobs → index pe0+i is the same element in all three.
761	            algo::prodigy_partials_step(params, st.param_init, grad,
762	                                        d_prev, pe0 + i, r_acc, s_acc);
763	        }
764	        // Deterministic in-CTA two-value reduction (fixed thread count) → thread0
765	        // publishes this CTA's (r,s) slot. No atomic.
766	        float r_block, s_block;
767	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
768	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
769	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
770	        // Owner block (CTA0 thread0): ascending owner-sum + EMA decay + accumulate +
771	        // d_coef + update_d, byte-matching launch_multi_tensor_prodigy_fused_reduce_step.
772	        if (cta == 0 && threadIdx.x == 0) {
773	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
774	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
775	            // Decay persisted scalars by beta3, then add this step's reduction.
776	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
777	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
778	            // d = max(d_prev, d_coef·r_ema/|s_ema|). prodigy_update_d does
779	            // max(d_prev, r/|s|) verbatim, so fold d_coef into the numerator copy
780	            // (persisted r_ema stays UNSCALED — returned/persisted, eager parity).
781	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
782	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
783	            st.prodigy_persist[1] = s_ema;
784	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
785	            d_bc[0]               = d_new;          // broadcast to all CTAs
786	        }
787	        bar.sync();   // B2.6b: d visible to every CTA before the apply
788	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
789	    }
790	
791	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
792	    //    2D weights (INTEGRATION-OPTSTAGES §3). IDENTICAL to the vit twin
793	    //    (fused_vit_megakernel.cuh P2.7) — same shared opt_stages_precompute.cuh
794	    //    helpers, same barrier sequence — only the per-model 2D table (dectc::
795	    //    kDecMuon2D, 11 matrices including tok[99,128]/pos[4,128]) and offset array
796	    //    (kDecOffsets) differ. For EACH 2D matrix all CTAs cooperate: buf=μ·buf+g
797	    //    (buf is the PERSISTENT m-slice — momentum state, NOT transient), ‖buf‖_F via
798	    //    per-CTA partials → inv_norm, X=buf·inv_norm, then ns_steps × { A=XXᵀ → AX=A·X
799	    //    → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap }, then the canonical muon_update_step
800	    //    apply (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (biases, LN γ/β)

800	    //    apply (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (biases, LN γ/β)
801	    //    take the AdamW aux tail in P3. The elementwise bodies CALL muon.h
802	    //    (muon_momentum_normalize_step via the phaseA buf body, muon_ns_combine_step,
803	    //    muon_update_step); the matmuls are the cited new device code (the eager path
804	    //    delegates to torch::mm/cuBLAS). Guarded so every other opt is byte-identical
805	    //    (no extra barriers / work).
806	    if constexpr (Opt == OptId::Muon) {
807	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
808	        PrecomputeWorkspace pw{};
809	        pw.muon_X            = muon_base;
810	        pw.muon_AX           = pw.muon_X   + dectc::kDecMuonMaxNumel;
811	        pw.muon_AAX          = pw.muon_AX  + dectc::kDecMuonMaxNumel;
812	        pw.muon_orth         = pw.muon_AAX + dectc::kDecMuonMaxNumel;
813	        pw.muon_A            = pw.muon_orth + dectc::kDecMuonMaxNumel;
814	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows;
815	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
816	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
817	        const int   ns_steps = 5;                 // bindings.cpp default
818	        for (int mi = 0; mi < dectc::kDecNumMuon2D; ++mi) {
819	            const dectc::DecMuon2D M = dectc::kDecMuon2D[mi];
820	            const int rows = M.rows, cols = M.cols;
821	            const int64_t numel = (int64_t)rows * cols;
822	            const int64_t off   = (int64_t)kDecOffsets[M.tidx];
823	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
824	            pw.muon_buf = st.exp_avg + off;
825	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
826	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
827	            bar.sync();
828	            muon_norm_reduce_phaseB(ctx, pw);
829	            bar.sync();
830	            muon_scale_X(numel, pw);
831	            bar.sync();
832	            // NS iterations. After each combine, orth holds the new iterate; swap so
833	            // the next iteration reads it as X. ns_steps swaps → final result is in
834	            // muon_X (the last combine wrote muon_orth, then we swapped → muon_X).
835	            for (int s = 0; s < ns_steps; ++s) {
836	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
837	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
838	                bar.sync();
839	                // AX = A X   (M=rows,N=cols,K=rows).
840	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
841	                bar.sync();
842	                // AAX = A (AX) (M=rows,N=cols,K=rows).
843	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
844	                bar.sync();
845	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
846	                bar.sync();
847	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
848	            }
849	            // Apply Muon: p = decay_factor·p + neg_lr_scale·orth  (muon.h:63-73).
850	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
851	            const float neg_lr_scale = -lr * scale;
852	            const float decay_factor = 1.0f - lr * st.wd;
853	            float* __restrict__ p = params + off;
854	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
855	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
856	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
857	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
858	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
859	        }
860	    }
861	
862	    // ── P2.45 (SuperGrok11/15 ONLY) staged into P3: the per-TENSOR meta-net mu
863	    //    precompute (INTEGRATION-OPTSTAGES §4/§5). SINGLE task-queue drain, NO grid
864	    //    barrier: each tensor T is SELF-CONTAINED — mu(T) = sg_rescale·phi(g[T],
865	    //    sharpness[T]) (per element) and, for SG11, the per-tensor cosine gate(T) =
866	    //    clamp(cos(g[T], mu[T]), 0, 1) depend ONLY on T's own elements (never on any
867	    //    other tensor's mu), so mu(+gate)→apply fuse into ONE body the SAME CTA owns
868	    //    end-to-end inside the EXISTING P3 drain (every thread of a CTA claims the same
869	    //    tensor t via the block-level task_slot, so the helper's __syncthreads/block-
870	    //    reduce are block-uniform and safe). NOT a separate full-queue mu pre-pass +
871	    //    a second apply drain (that would silently no-op — see the SG11 block in
872	    //    opt_stages_precompute.cuh). The phi weights (per-TENSOR weight set) are staged
873	    //    to SMEM ONCE per block before the drain. SG15's gate is the host scalar st.gate
874	    //    (no cosine stage); SG11 binds the per-tensor gate the helper returns. sharpness
875	    //    (the 2nd MLP input) was produced by P2.4 (or the cached prior step).
876	    __shared__ float sg_sW1[kSgPhiHidden * 2];
877	    __shared__ float sg_sb1[kSgPhiHidden];
878	    __shared__ float sg_sW2[kSgPhiHidden];
879	    if constexpr (Opt == OptId::SuperGrok11 || Opt == OptId::SuperGrok15) {
880	        sg_stage_phi_weights<kSgPhiHidden>(st.sg_phi_W1, st.sg_phi_b1, st.sg_phi_W2,
881	                                           sg_sW1, sg_sb1, sg_sW2);   // syncs
882	    }
883	
884	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
885	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
886	    st.lr = lr;
887	    {
888	        __shared__ int task_slot;
889	        TaskQueue q = ctx.queue();
890	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
891	             t = q.next_block(&task_slot)) {
892	            const int n = kDecSizes[t];
893	            const int64_t off = (int64_t)kDecOffsets[t];
894	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
895	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
896	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
897	            if constexpr (Opt == OptId::Muon) {
898	                if (dectc::dec_is_muon_2d(t)) continue;
899	            }
900	            FusedOptState ts = rebase_state<Opt>(st, off);
901	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
902	            //     t == the tensor's flat named_parameters() layer index (the
903	            //     work-steal task id maps 1:1 to kDecOffsets order == the eager
904	            //     enumeration order, so t IS the eager layer index). bc1 must be
905	            //     rebased TOO (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager
906	            //     (~9.6× on the deepest layer); bc2 stays global (β2 not layer-wise).
907	            if constexpr (Opt == OptId::GrokAdamW) {
908	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
909	                ts.beta1 = b1;
910	                ts.bc1   = 1.0f - powf(b1, (float)step);
911	            }
912	            // SuperGrok11/15 meta-net mu (+ SG11 per-tensor gate) precompute for THIS
913	            // tensor, BEFORE the apply reads ts.mu/ts.gate. mu(T)=sg_rescale·phi(g,
914	            // sharpness) over [off,off+n); SG11 also computes the clamped cosine gate(T)
915	            // (block-uniform __syncthreads/reduce — the whole CTA owns t). SG15's gate is
916	            // st.gate (host sigmoid(accuracy)). Helpers index grad/sharpness/mu by off+i,
917	            // so pass the BASE pointers (st.mu, grad, st.sharpness) + off; the apply then
918	            // reads ts.mu (== st.mu+off). phi_b2 read on-device from sg_phi_W2[H].
919	            if constexpr (Opt == OptId::SuperGrok11) {
920	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
921	                                                           : st.sg_phi_b2;
922	                const float g8 = sg11_precompute_mu_and_gate_for_tensor<kSgPhiHidden>(
923	                    st.mu, grad, st.sharpness, sg_sW1, sg_sb1, sg_sW2,
924	                    b2, st.sg_rescale, off, n);
925	                ts.gate = g8;            // per-tensor cosine gate the apply tail reads
926	                __syncthreads();         // mu(T) fully written + gate broadcast before apply
927	            } else if constexpr (Opt == OptId::SuperGrok15) {
928	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
929	                                                           : st.sg_phi_b2;
930	                sg15_precompute_mu_for_tensor<kSgPhiHidden>(
931	                    st.mu, grad, st.sharpness, sg_sW1, sg_sb1, sg_sW2,
932	                    b2, st.sg_rescale, off, n);
933	                // ts.gate stays = st.gate (the host sigmoid(accuracy) scalar).
934	                __syncthreads();         // mu(T) visible before the apply reads it
935	            }
936	            float* __restrict__ p = params + off;
937	            const float* __restrict__ gg = grad + off;
938	            if constexpr (Opt == OptId::Muon) {
939	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:99-125 routes
940	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
941	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
942	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
943	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
944	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
945	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
946	                // bc1/bc2 are device-computed from aux_beta^step (kept out of the mirror
947	                // to shrink the host ABI; fp32 powf, tol 2e-3 ample). apply_optimizer<Muon>
948	                // would deref st.orth (NS dir, only valid for 2D), so route directly to
949	                // adamw_step with the aux hyperparameters — IDENTICAL to the vit twin.
950	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
951	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
952	                for (int i = threadIdx.x; i < n; i += blockDim.x)
953	                    algo::adamw_step<float, float>(
954	                        p, ts.exp_avg, ts.exp_avg_sq, gg,
955	                        st.aux_lr, st.aux_beta1, st.aux_beta2, ts.eps, ts.wd,
956	                        a_bc1, a_bc2, (int64_t)i);
957	            } else {
958	                for (int i = threadIdx.x; i < n; i += blockDim.x)
959	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
960	            }
961	        }
962	    }
963	}
