965	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
966	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas),
967	// so any cap is hang-safe as long as the workspace + dW-tile/embedding ownership
968	// use the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
969	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
970	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
971	// nCTA (the dW/embedding owner maps are functions of nCTA).
972	template <OptId Opt>
973	cudaError_t launch_fused_decoder_megakernel_tc(
974	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
975	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
976	        int ncta_cap = 0) {
977	    int dev = 0;
978	    cudaError_t err = cudaGetDevice(&dev);
979	    if (err != cudaSuccess) return err;
980	    int n_sms = 0;
981	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
982	    if (err != cudaSuccess) return err;
983	
984	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
985	    // (0 here — DecTcSmem is static). If the static smem + 200-reg consumer
986	    // can't place one block/SM, REFUSE (the grid barrier would hang).
987	    int occ = 0;
988	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
989	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
990	        /*dynamicSMemBytes=*/0);
991	    if (err != cudaSuccess) return err;
992	    if (occ < 1) return cudaErrorLaunchOutOfResources;
993	
994	    unsigned launch_ctas = (unsigned)n_sms;
995	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
996	    ctx.n_ctas = launch_ctas;
997	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms,
998	    // AND it guarantees full token tiles for the projections). NO G-divisibility
999	    // guard: the split-K dW uses a FLOOR-BALANCED K-partition (dectc_dw_run_tile_
1000	    // splitk) that sums to KS exactly for any KS≥G, so it works at the production
1001	    // truncated B (e.g. 4176, where head KS=B/16=261 is NOT divisible by G=4).
1002	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
1003	
1004	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1005	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1006	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1007	
1008	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
1009	    fused_decoder_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
1010	        ctx, params, tok, grad, lr, step, st);
1011	    return cudaGetLastError();
1012	}
